def table(headers,rows):
    clean=lambda v:str(v).replace('|','/').replace('\n',' ')
    return '\n| '+' | '.join(headers)+' |\n| '+' | '.join('---'for _ in headers)+' |\n'+''.join('| '+' | '.join(clean(v) for v in row)+' |\n'for row in rows)
